/*---
description: az locale casing retains a combining dot after J
features: [ts-unicode-locale-case, ts-unicode-sequences, ts-strings]
---*/
// Generated by tooling/unicode-cases/locale-case.ts; expected values are from Node.
// Oracle: Node 24.20.0; Unicode 17.0; ICU 78.3.
// docs/foundations/unicode.md: locale-sensitive casing and Staying identical to node.
const input = "\u004a\u0307";
const lower = input.toLocaleLowerCase("\u0061\u007a");
const upper = input.toLocaleUpperCase("\u0061\u007a");
assert.sameValue(lower, "\u006a\u0307");
assert.sameValue(lower.length, 2);
assert.sameValue(upper, "\u004a\u0307");
assert.sameValue(upper.length, 2);
